_PATS = []


def set_lang(lang):
    global LANG, _PATS
    LANG = lang if lang in ("en", "ro") else "en"
    _PATS = []
    for en, ro in sorted(TEMPLATES.items(), key=lambda kv: -len(kv[0])):      # longest (most specific) first
        parts = en.split("{}")
        rx = re.compile("^" + "(.*?)".join(re.escape(p) for p in parts) + "$", re.S)
        _PATS.append((rx, ro))


def _one(s):
    if s in EXACT:
        return EXACT[s]
    st = s.strip()
    if st != s and st in EXACT:
        return s.replace(st, EXACT[st])
    for rx, ro in _PATS:
        m = rx.match(s)
        if m:
            vals = [_words(T(g)) if g else g for g in m.groups()]
            try:
                return ro.format(*vals)
            except (IndexError, KeyError, ValueError):
                return s
    return None


_CAT = re.compile(r"\b(bride|groom|couple|church|venue|party|drone)\b")


def _words(s):
    """Category names inside a value ("drone (10x), couple (8x)")."""
    return _CAT.sub(lambda m: EXACT.get(m.group(1), m.group(1)), s) if isinstance(s, str) else s


def T(s):
    """The text in the chosen language (unchanged in English or when unknown)."""
    if LANG == "en" or not isinstance(s, str) or not s or not re.search(r"[A-Za-z]", s):
        return s
    r = _one(s)
    if r is not None:
        return r
    if "<" in s and ">" in s:                       # HTML: translate every text piece between the tags
        return re.sub(r"(^|>)([^<]+)(?=<|$)", lambda m: m.group(1) + (_one(m.group(2)) or m.group(2)), s)
    if "\n" in s:
        return "\n".join(T(x) for x in s.split("\n"))
    return s


# ---------------------------------------------------------------- Qt hooks
def install():
    from PySide6 import QtWidgets as W, QtGui as G, QtCore as Cc

    def wrap(cls, name, idx=0):
        orig = getattr(cls, name)

        def f(self, *a, **k):
            if LANG != "en" and len(a) > idx and isinstance(a[idx], str):
                a = list(a)
                a[idx] = T(a[idx])
            return orig(self, *a, **k)
        setattr(cls, name, f)

    for cls, name, idx in ((W.QLabel, "setText", 0), (W.QAbstractButton, "setText", 0), (W.QWidget, "setToolTip", 0),
                           (W.QWidget, "setWindowTitle", 0), (W.QLineEdit, "setPlaceholderText", 0),
                           (W.QTabWidget, "setTabText", 1),
                           (W.QTableWidgetItem, "setText", 0), (W.QListWidgetItem, "setText", 0)):
        wrap(cls, name, idx)
    # drop-down lists: ONLY those marked setProperty("i18n", True) (they work by position); in the others the text is a
    # value read back by the code (presets, camera roles, sequence settings) and must stay as it is
    o_add = W.QComboBox.addItems
    W.QComboBox.addItems = lambda self, items: o_add(self, [T(x) for x in items] if self.property("i18n") else items)
    o_tab = W.QTabWidget.addTab
    W.QTabWidget.addTab = lambda self, w, *a: o_tab(self, w, *[T(x) if isinstance(x, str) else x for x in a])
    o_hdr = W.QTableWidget.setHorizontalHeaderLabels
    W.QTableWidget.setHorizontalHeaderLabels = lambda self, ls: o_hdr(self, [T(x) for x in ls])
    o_set = W.QTableWidget.setItem

    def set_item(self, r, c, it):
        if LANG != "en" and it is not None:
            it.setText(T(it.text()))
        return o_set(self, r, c, it)
    W.QTableWidget.setItem = set_item
    o_draw = G.QPainter.drawText

    def draw(self, *a):
        if LANG != "en":
            a = [T(x) if isinstance(x, str) else x for x in a]
        return o_draw(self, *a)
    G.QPainter.drawText = draw
    for name in ("question", "warning", "information", "critical"):
        o = getattr(W.QMessageBox, name)
        setattr(W.QMessageBox, name, staticmethod(lambda *a, _o=o, **k: _o(*[T(x) if isinstance(x, str) else x for x in a], **k)))
    for name in ("getOpenFileName", "getOpenFileNames", "getSaveFileName", "getExistingDirectory"):
        o = getattr(W.QFileDialog, name)

        def fd(*a, _o=o, **k):
            a = list(a)
            if len(a) > 1 and isinstance(a[1], str):
                a[1] = T(a[1])                      # the caption (paths and filters are left as they are)
            return _o(*a, **k)
        setattr(W.QFileDialog, name, staticmethod(fd))
    o_txt = W.QInputDialog.getText
    W.QInputDialog.getText = staticmethod(lambda parent, title, label, *a, **k: o_txt(parent, T(title), T(label), *a, **k))

    class Sweep(Cc.QObject):
        """Every widget made with a text in its constructor: translated once, when it is first shown."""
        def eventFilter(self, obj, ev):
            if LANG != "en" and ev.type() == Cc.QEvent.Show and isinstance(obj, W.QWidget) and not obj.property("_i18n"):
                sweep(obj)
            return False
    app = W.QApplication.instance()
    app._i18n_sweep = Sweep()
    app.installEventFilter(app._i18n_sweep)


def sweep(root):
    from PySide6 import QtWidgets as W
    for w in [root] + root.findChildren(W.QWidget):
        if w.property("_i18n"):
            continue
        w.setProperty("_i18n", True)
        if isinstance(w, (W.QLabel, W.QAbstractButton)) and w.text():
            w.setText(w.text())                      # goes through the hook
        if w.toolTip():
            w.setToolTip(w.toolTip())
        if isinstance(w, W.QLineEdit) and w.placeholderText():
            w.setPlaceholderText(w.placeholderText())
        if isinstance(w, W.QTabWidget):
            for i in range(w.count()):
                w.setTabText(i, w.tabText(i))
        if isinstance(w, W.QComboBox) and w.property("i18n"):
            for i in range(w.count()):
                w.setItemText(i, T(w.itemText(i)))
        if w.isWindow() and w.windowTitle():
            w.setWindowTitle(w.windowTitle())


set_lang(LANG)
